const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });

  // 1. Geometry & Time Definitions
  // Approximate location near Banamepe along the Digul River, Papua, Indonesia.
  // Latitude: -5.9, Longitude: 139.75
  const point = ee.Geometry.Point(139.75, -5.9);
  const aoi = point.buffer(5000); // 5 km buffer around the point

  const startYear = 2002;
  const endYear = 2019;
  const scale = 30; // Hansen data resolution is 30m

  // 2. Data Acquisition & Check
  const hansen = ee.Image('Hansen/GFC-2023-V1_7');

  // Check if Hansen data is available (it's a static image, so always available if ID is correct)
  if (hansen.bandNames().size().getInfo() === 0) {
    console.log("Error: Hansen GFC dataset not loaded correctly.");
    console.log("D");
    return;
  }

  // Define a forest threshold (e.g., 10% tree cover)
  const treeCoverThreshold = 10;

  // Function to calculate forest area for a given year
  function calculateForestArea(image, geometry, year) {
    const treecover2000 = image.select('treecover2000');
    const lossyear = image.select('lossyear');

    // Forest is defined as pixels with >= treeCoverThreshold% canopy cover in 2000
    // that have NOT been lost by the specified year.
    // lossyear values are 1-19 for 2001-2019.
    const forestBeforeYear = treecover2000.gte(treeCoverThreshold);
    const notLostByYear = lossyear.eq(0) // Pixels not lost at all up to 2019 (coded 0 means no loss)
      .or(lossyear.gt(year - 2000)); // or lost after the given year

    const forestMask = forestBeforeYear.and(notLostByYear);

    // Calculate area of forest pixels
    // Multiply by image area to get actual area, then sum up within the geometry.
    const forestAreaImage = forestMask.multiply(ee.Image.pixelArea()).divide(1e4); // km²

    const stats = forestAreaImage.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: scale,
      maxPixels: 1e9,
      crs: 'EPSG:4326' // Specify CRS for consistency
    });

    return stats.get('sum');
  }

  // 3. Processing & Calculation
  const forestArea2002 = await calculateForestArea(hansen, aoi, startYear).getInfo();
  const forestArea2019 = await calculateForestArea(hansen, aoi, endYear).getInfo();

  // Validate results
  if (forestArea2002 === null || isNaN(forestArea2002) ||
      forestArea2019 === null || isNaN(forestArea2019)) {
    console.log("C3");
    return;
  }

  // If initial forest area is 0, it implies no valid forest pixels in the AOI for 2002.
  // This could lead to a misleading 'decrease' if there was no forest to begin with.
  // We check for C2 (no valid pixels).
  if (forestArea2002 === 0 && forestArea2019 === 0) {
    console.log("No valid forest pixels found in 2002 or 2019 in the AOI.");
    console.log("C2");
    return;
  }

  // 4. Comparison and Final Answer
  const decreased = forestArea2019 < forestArea2002;

  console.log(`Forest Area in ${startYear} (km²): ${forestArea2002 !== null ? forestArea2002.toFixed(2) : 'N/A'}`);
  console.log(`Forest Area in ${endYear} (km²): ${forestArea2019 !== null ? forestArea2019.toFixed(2) : 'N/A'}`);
  console.log(`Change: ${((forestArea2019 - forestArea2002) / forestArea2002 * 100).toFixed(2)}%`);

  if (decreased) {
    console.log("A");
  } else {
    console.log("B");
  }
}

initEE();
